param([ValidateSet('Configure','Restore')][string]$Action = 'Configure')

$ErrorActionPreference = 'Stop'
$go2InterfaceIndex = 6
$go2ExpectedMac = 'B0-25-AA-85-62-16'
$go2Address = '192.168.123.99'
$go2BackupPath = Join-Path $PSScriptRoot 'network-before.json'
$go2StatusPath = Join-Path $PSScriptRoot 'network-status.json'
$go2AddedAddress = $false
$go2DisabledDhcp = $false

function Write-Go2Status([string]$State, [string]$Message) {
    [pscustomobject]@{
        action = $Action
        state = $State
        message = $Message
        interface_index = $go2InterfaceIndex
        temporary_address = $go2Address
        recorded_utc = [DateTime]::UtcNow.ToString('o')
    } | ConvertTo-Json | Set-Content -LiteralPath $go2StatusPath -Encoding UTF8
}

try {
    $go2IsAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    if (-not $go2IsAdmin) { throw 'Administrator rights are required for this dedicated Ethernet adapter.' }
    $go2Adapter = @(Get-NetAdapter | Where-Object ifIndex -eq $go2InterfaceIndex)
    if ($go2Adapter.Count -ne 1 -or $go2Adapter[0].MacAddress -ne $go2ExpectedMac) {
        throw 'Adapter identity changed; no network changes made.'
    }
    if ($Action -eq 'Restore') {
        if (-not (Test-Path -LiteralPath $go2BackupPath)) { throw 'Original network snapshot is missing.' }
        $go2Before = Get-Content -LiteralPath $go2BackupPath -Raw | ConvertFrom-Json
        Get-NetIPAddress -InterfaceIndex $go2InterfaceIndex -AddressFamily IPv4 -PolicyStore ActiveStore -ErrorAction SilentlyContinue |
            Where-Object IPAddress -eq $go2Address |
            Remove-NetIPAddress -Confirm:$false -ErrorAction Stop
        Set-NetIPInterface -InterfaceIndex $go2InterfaceIndex -AddressFamily IPv4 -Dhcp $go2Before.dhcp -PolicyStore ActiveStore
        Write-Go2Status 'restored' 'Removed only the test address and restored the recorded DHCP setting.'
        exit 0
    }
    if ($go2Adapter[0].Status -ne 'Up') { throw 'Ethernet cable link is not up.' }
    $go2Current = @(Get-NetIPAddress -InterfaceIndex $go2InterfaceIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue)
    $go2OtherStatic = @($go2Current | Where-Object { $_.IPAddress -notlike '169.254.*' -and $_.IPAddress -ne $go2Address })
    if ($go2OtherStatic.Count -gt 0) { throw 'Adapter already has another IPv4 configuration; refusing to overwrite it.' }
    $go2DefaultBefore = @(Get-NetRoute -AddressFamily IPv4 | Where-Object DestinationPrefix -eq '0.0.0.0/0' |
        Select-Object InterfaceIndex,NextHop)
    $go2DhcpBefore = (Get-NetIPInterface -InterfaceIndex $go2InterfaceIndex -AddressFamily IPv4).Dhcp.ToString()
    if (-not (Test-Path -LiteralPath $go2BackupPath)) {
        [pscustomobject]@{
            interface_index = $go2InterfaceIndex
            mac = $go2ExpectedMac
            dhcp = $go2DhcpBefore
            ipv4 = @($go2Current | Select-Object IPAddress,PrefixLength,PrefixOrigin)
            default_routes = $go2DefaultBefore
            recorded_utc = [DateTime]::UtcNow.ToString('o')
        } | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $go2BackupPath -Encoding UTF8
    }
    if (-not ($go2Current | Where-Object IPAddress -eq $go2Address)) {
        if ($go2DhcpBefore -eq 'Enabled') {
            Set-NetIPInterface -InterfaceIndex $go2InterfaceIndex -AddressFamily IPv4 -Dhcp Disabled -PolicyStore ActiveStore
            $go2DisabledDhcp = $true
        }
        New-NetIPAddress -InterfaceIndex $go2InterfaceIndex -IPAddress $go2Address -PrefixLength 24 -PolicyStore ActiveStore | Out-Null
        $go2AddedAddress = $true
    }
    for ($go2Attempt = 0; $go2Attempt -lt 8; $go2Attempt++) {
        $go2Assigned = Get-NetIPAddress -InterfaceIndex $go2InterfaceIndex -IPAddress $go2Address -AddressFamily IPv4
        if ($go2Assigned.AddressState.ToString() -eq 'Duplicate') { throw 'The selected address conflicts with another device.' }
        if ($go2Assigned.AddressState.ToString() -eq 'Preferred') { break }
        Start-Sleep -Seconds 1
    }
    if ($go2Assigned.AddressState.ToString() -ne 'Preferred') { throw 'The test address did not become usable.' }
    $go2DefaultAfter = @(Get-NetRoute -AddressFamily IPv4 | Where-Object DestinationPrefix -eq '0.0.0.0/0' |
        Select-Object InterfaceIndex,NextHop)
    if (($go2DefaultBefore | ConvertTo-Json -Compress) -ne ($go2DefaultAfter | ConvertTo-Json -Compress)) {
        throw 'Default route changed during setup; rolling back test changes.'
    }
    Write-Go2Status 'configured' 'Temporary Ethernet IPv4 address is preferred; no default gateway was added.'
} catch {
    $go2Failure = $_.Exception.Message
    if ($go2AddedAddress) {
        Get-NetIPAddress -InterfaceIndex $go2InterfaceIndex -AddressFamily IPv4 -PolicyStore ActiveStore -ErrorAction SilentlyContinue |
            Where-Object IPAddress -eq $go2Address |
            Remove-NetIPAddress -Confirm:$false -ErrorAction SilentlyContinue
    }
    if ($go2DisabledDhcp) {
        Set-NetIPInterface -InterfaceIndex $go2InterfaceIndex -AddressFamily IPv4 -Dhcp Enabled -PolicyStore ActiveStore -ErrorAction SilentlyContinue
    }
    Write-Go2Status 'failed' $go2Failure
    exit 1
}

