[CmdletBinding()]
param(
    [ValidateSet('Start','Watch','Status','Stop')][string]$Mode = 'Start',
    [ValidatePattern('^[A-Za-z0-9_.-]+$')][string]$SshAlias = 'go2',
    [ValidateRange(1,65535)][int]$LocalProxyPort = 17890,
    [ValidateRange(1,65535)][int]$RemoteProxyPort = 17890
)
$ErrorActionPreference = 'Stop'
$sshExe = (Get-Command ssh.exe -ErrorAction Stop).Source
$stateDir = Join-Path $env:LOCALAPPDATA "Go2Proxy\$SshAlias-$LocalProxyPort-$RemoteProxyPort"
[void][IO.Directory]::CreateDirectory($stateDir)
$logPath = Join-Path $stateDir 'proxy.log'
$statusPath = Join-Path $stateDir 'status.json'
$stopPath = Join-Path $stateDir 'stop.request'
$mutexName = "Local\Go2Proxy-$SshAlias-$LocalProxyPort-$RemoteProxyPort"
$sshBase = @('-n','-T','-o','BatchMode=yes','-o','StrictHostKeyChecking=yes',
    '-o','ConnectTimeout=5','-o','ServerAliveInterval=5','-o','ServerAliveCountMax=2')

function Write-ProxyLog([string]$Message) {
    Add-Content -LiteralPath $logPath -Encoding UTF8 -Value ((Get-Date -Format 'yyyy-MM-dd HH:mm:ss') + ' ' + $Message)
}
function Test-LocalProxy {
    $socket = [Net.Sockets.TcpClient]::new()
    try { $task = $socket.ConnectAsync('127.0.0.1', $LocalProxyPort); return ($task.Wait(1500) -and $socket.Connected) }
    catch { return $false } finally { $socket.Dispose() }
}
function Test-Watcher {
    $mutex = [Threading.Mutex]::new($false, $mutexName)
    $acquired = $false
    try {
        try { $acquired = $mutex.WaitOne(0) } catch [Threading.AbandonedMutexException] { $acquired = $true }
        return (-not $acquired)
    } finally { if ($acquired) { $mutex.ReleaseMutex() }; $mutex.Dispose() }
}
function Invoke-Remote([string]$Command) {
    # Commands are fixed here; no credentials or user shell fragments are interpolated.
    $remoteArg = '"' + $Command.Replace('"', '\"') + '"'
    $info = [Diagnostics.ProcessStartInfo]::new()
    $info.FileName = $sshExe
    $info.Arguments = ($sshBase -join ' ') + ' ' + $SshAlias + ' ' + $remoteArg
    $info.UseShellExecute = $false; $info.CreateNoWindow = $true
    $info.RedirectStandardOutput = $true; $info.RedirectStandardError = $true
    $p = [Diagnostics.Process]::new(); $p.StartInfo = $info
    try {
        [void]$p.Start()
        $stdout = $p.StandardOutput.ReadToEndAsync(); $stderr = $p.StandardError.ReadToEndAsync()
        if (-not $p.WaitForExit(22000)) {
            $p.Kill(); [void]$p.WaitForExit(2000)
            return @{ Code = 124; Out = ''; Error = 'SSH probe timed out.' }
        }
        return @{ Code = $p.ExitCode; Out = $stdout.Result.Trim(); Error = $stderr.Result.Trim() }
    } finally { $p.Dispose() }
}
function Test-RemoteHttps {
    # HTTP response proves proxy CONNECT/TLS reachability, not Codex model/account health.
    $r = Invoke-Remote "curl --noproxy '' --proxy http://127.0.0.1:$RemoteProxyPort --connect-timeout 4 --max-time 10 -sS -o /dev/null -w '%{http_code}' https://auth.openai.com/codex/device"
    return @{ Ok = ($r.Code -eq 0 -and $r.Out -match '^[1-5][0-9][0-9]$'); Http = $r.Out; Error = $r.Error }
}
function Save-Status([string]$State, [string]$Detail) {
    $value = [ordered]@{
        updated_at = (Get-Date).ToString('o'); state = $State; detail = $Detail
        watcher_pid = $PID; ssh_alias = $SshAlias
        local_proxy = "127.0.0.1:$LocalProxyPort"; remote_proxy = "127.0.0.1:$RemoteProxyPort"
    }
    $tmpPath = Join-Path $stateDir 'status.tmp'
    [IO.File]::WriteAllText($tmpPath, ($value | ConvertTo-Json), [Text.UTF8Encoding]::new($false))
    Move-Item -LiteralPath $tmpPath -Destination $statusPath -Force
    Write-ProxyLog "$State $Detail"
}

if ($Mode -eq 'Stop') {
    if (Test-Watcher) {
        [IO.File]::WriteAllText($stopPath, 'stop')
        Write-Host 'Stop requested. Only the tunnel created by this helper will close (within about 50 seconds).'
    } else { Write-Host 'No managed proxy helper is running.' }
    exit 0
}
if ($Mode -eq 'Status') {
    Write-Host "Background helper running: $(Test-Watcher)"
    Write-Host "Computer proxy listening: $(Test-LocalProxy)"
    if (Test-Path -LiteralPath $statusPath) { Get-Content -LiteralPath $statusPath }
    $check = Test-RemoteHttps
    Write-Host "Live robot HTTPS check: $($check.Ok); HTTP=$($check.Http)"
    if (-not $check.Ok) { Write-Host $check.Error }
    Write-Host "Log: $logPath"
    if ($check.Ok) { exit 0 } else { exit 1 }
}
if ($Mode -eq 'Start') {
    if (-not (Test-LocalProxy)) { throw "Computer HTTP proxy 127.0.0.1:$LocalProxyPort is not listening. Start your VPN/proxy first." }
    Write-Host 'Checking passwordless SSH to Go2...'
    $login = Invoke-Remote 'printf GO2_SSH_OK'
    if ($login.Code -ne 0 -or $login.Out -ne 'GO2_SSH_OK') { throw "SSH to $SshAlias failed. Check Ethernet, robot power and SSH alias. $($login.Error)" }
    $clockRead = Invoke-Remote 'date +%s'
    $computerEpoch = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    if ($clockRead.Code -ne 0 -or $clockRead.Out -notmatch '^\d+$') { throw 'Cannot read robot time.' }
    if ([Math]::Abs([double]$clockRead.Out - $computerEpoch) -gt 300) {
        Write-Host 'Robot clock differs from the computer by over 5 minutes; synchronizing for TLS.'
        $sync = Invoke-Remote "sudo -n date -u -s @$computerEpoch"
        if ($sync.Code -ne 0) {
            Write-Host 'Enter the robot sudo password if requested. It is not saved.'
            & $sshExe -t -o BatchMode=yes -o StrictHostKeyChecking=yes -o ConnectTimeout=5 $SshAlias "sudo date -u -s @$computerEpoch"
            if ($LASTEXITCODE -ne 0) { throw 'Clock sync failed. Fix the robot clock and run Start again.' }
        }
        Write-Host 'Robot clock synchronized.'
    }
    if (-not (Test-Watcher)) {
        if (Test-Path -LiteralPath $stopPath) { Remove-Item -LiteralPath $stopPath }
        $psExe = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
        $watchArgs = '-NoProfile -ExecutionPolicy Bypass -File "' + $PSCommandPath + '" -Mode Watch -SshAlias ' + $SshAlias + ' -LocalProxyPort ' + $LocalProxyPort + ' -RemoteProxyPort ' + $RemoteProxyPort
        Start-Process -FilePath $psExe -ArgumentList $watchArgs -WindowStyle Hidden | Out-Null
        Write-Host 'Started a background helper with automatic reconnect.'
    } else { Write-Host 'Background helper already running; no duplicate started.' }
    $healthy = $false
    for ($i = 0; $i -lt 3; $i++) {
        Start-Sleep -Seconds 2
        $check = Test-RemoteHttps
        if ($check.Ok) { $healthy = $true; break }
    }
    if ($healthy) {
        Write-Host "READY: Go2 HTTPS works through the computer proxy (HTTP $($check.Http))." -ForegroundColor Green
        Write-Host 'You may close this window. Keep the computer awake, VPN running and Ethernet connected.'
        Write-Host 'HTTPS reachability is verified; this is not a model/account test.'
    } else {
        Write-Warning 'Helper started, but robot HTTPS is not yet verified. It will keep retrying.'
        Write-Host $check.Error
        if (Test-Path -LiteralPath $statusPath) { Get-Content -LiteralPath $statusPath }
    }
    Write-Host "Log: $logPath"
    if ($healthy) { exit 0 } else { exit 1 }
}

# Hold one mutex per target for the entire background lifetime, including retries.
$watchMutex = [Threading.Mutex]::new($false, $mutexName)
$ownsMutex = $false; $tunnel = $null
try {
    try { $ownsMutex = $watchMutex.WaitOne(0) } catch [Threading.AbandonedMutexException] { $ownsMutex = $true }
    if (-not $ownsMutex) { exit 0 }
    Save-Status 'starting' 'Background reconnect helper started.'
    while (-not (Test-Path -LiteralPath $stopPath)) {
        try {
            if ($tunnel -and $tunnel.HasExited) {
                Save-Status 'reconnecting' "SSH tunnel exited with code $($tunnel.ExitCode)."
                $tunnel.Dispose(); $tunnel = $null
            }
            if (-not (Test-LocalProxy)) {
                Save-Status 'waiting_for_computer_proxy' 'Start the computer VPN/proxy.'
            } else {
                if (-not $tunnel) {
                    $listener = Invoke-Remote "ss -ltnH sport = :$RemoteProxyPort"
                    if ($listener.Code -ne 0) { Save-Status 'waiting_for_ssh' $listener.Error }
                    elseif ($listener.Out) {
                        $check = Test-RemoteHttps
                        if ($check.Ok) { Save-Status 'using_existing_tunnel' "HTTPS HTTP=$($check.Http). Existing listener is not owned by this helper." }
                        else { Save-Status 'port_busy_unhealthy' 'Existing remote listener is unhealthy. Not killing unknown processes; inspect the old tunnel.' }
                    } else {
                        $tunnelArgs = @('-N','-T','-o','BatchMode=yes','-o','StrictHostKeyChecking=yes',
                            '-o','ExitOnForwardFailure=yes','-o','ConnectTimeout=5',
                            '-o','ServerAliveInterval=10','-o','ServerAliveCountMax=3',
                            '-R',"127.0.0.1:${RemoteProxyPort}:127.0.0.1:${LocalProxyPort}",$SshAlias)
                        $tunnel = Start-Process -FilePath $sshExe -ArgumentList $tunnelArgs -WindowStyle Hidden -PassThru -RedirectStandardError (Join-Path $stateDir 'ssh-stderr.log')
                        Save-Status 'connecting' "Created SSH tunnel PID=$($tunnel.Id)."
                        Start-Sleep -Seconds 1
                    }
                }
                if ($tunnel -and -not $tunnel.HasExited) {
                    $check = Test-RemoteHttps
                    if ($check.Ok) { Save-Status 'ready' "HTTPS HTTP=$($check.Http); tunnel PID=$($tunnel.Id)." }
                    else { Save-Status 'https_unavailable' $check.Error }
                }
            }
        } catch { Save-Status 'retrying' $_.Exception.Message }
        for ($i = 0; $i -lt 15 -and -not (Test-Path -LiteralPath $stopPath); $i++) { Start-Sleep -Seconds 1 }
    }
} finally {
    if ($ownsMutex) {
        if ($tunnel) {
            if (-not $tunnel.HasExited) { $tunnel.Kill(); [void]$tunnel.WaitForExit(3000) }
            $tunnel.Dispose()
        }
        Save-Status 'stopped' 'Managed tunnel closed; unrelated SSH connections left alone.'
        $watchMutex.ReleaseMutex()
    }
    $watchMutex.Dispose()
}

