def prepare_baseline(snapshot, query_original_avoidance):
    """Complete blocking work BEFORE copying and validating the Feedback origin."""
    original=query_original_avoidance()
    status=classify(original[0],original[1])
    if status!='enabled':raise RuntimeError(json.dumps({'reason':'avoidance_'+status,'raw_code':original[0],'raw_value':original[1]}))
    state,now,reason=checked_snapshot(snapshot)
    if reason:raise RuntimeError('fresh_baseline_'+reason)
    low=state.get('motors')
    if not low or not 0<=now-low['t']<.25:raise RuntimeError('fresh_baseline_motor_state_stale')
    if any(low['errors']) or low['fan_error']:raise RuntimeError('fresh_baseline_motor_fault')
    if state['remote'].get('soc',0)<25:raise RuntimeError('fresh_baseline_battery')
    b=state['sport']
    if math.hypot(*b['velocity'][:2])>=.035 or abs(b['yaw_speed'])>=.06:raise RuntimeError('fresh_baseline_not_stationary')
    return state,now,original[1]


def run(a):
