def guard_reason(s, now, standing=True):
    if not s.get('sport') or not s.get('remote'): return 'missing_state'
    b, r = s['sport'], s['remote']
    if any(not 0 <= now - x['t'] < .25 for x in (b, r)): return 'stale_state'
    numbers = b['position'] + b['velocity'] + b['rpy'] + r['axes'] + [b['height'], b['yaw_speed']]
    if not all(math.isfinite(x) for x in numbers): return 'nonfinite_state'
    if r['keys'] or max(map(abs, r['axes'])) > .05: return 'remote_takeover'
    if max(map(abs, b['rpy'][:2])) > .35: return 'attitude_limit'
    if standing and b['code'] not in (100, 1002, 1013, 1015, 2010): return 'mode_changed'
    if standing and not .20 <= b['height'] <= .45: return 'height_limit'
    if math.hypot(*b['velocity'][:2]) > .50 or abs(b['yaw_speed']) > .45: return 'velocity_limit'
    return None


