"""V2 state-machine confirmation; no hardware access or command publishing."""
import math


def classic_gate(state, now, requested_at, active, stable_since):
    sport = state.get('sport', {})
    age = now - sport.get('t', float('-inf'))
    if not 0 <= age < .25:
        return None, False, 'classic_mode_state_stale'
    if active:
        return stable_since, sport.get('code') == 2010, (
            None if sport.get('code') == 2010 else 'classic_mode_lost')
    if now - requested_at >= .75:
        return None, False, 'classic_mode_confirmation_timeout'
    quiet = (math.hypot(*sport.get('velocity', [99, 99])[:2]) < .035
             and abs(sport.get('yaw_speed', 99)) < .06)
    if sport.get('code') != 2010 or not quiet:
        return None, False, None
    stable_since = now if stable_since is None else stable_since
    return stable_since, now - stable_since >= .15, None


def restored_fsm(result):
    """StopMove resets parameters; require observed original FSM, not its return code."""
    original = result.get('before_state', {}).get('sport', {}).get('code')
    observed = result.get('after_state', {}).get('sport', {}).get('code')
    return original == 100 and observed == original

