import unittest
from fast_prepare import wait_ready


class PreparationTests(unittest.TestCase):
    def run_case(self, worker_at=0., fresh=True, obstacle=False, guard=None):
        clock = [0.]
        class Pipe:
            def poll(self): return clock[0] >= worker_at
            def recv(self): return {'ready': True}
        return wait_ready([Pipe()], lambda: {'range': {'t': clock[0]}},
                          lambda: {'available': True, 'frame': 'base_link',
                                   't': clock[0] if fresh else -1., 'obstacle': obstacle},
                          lambda s,t: guard, timeout=1.5, clock=lambda: clock[0],
                          sleep=lambda d: clock.__setitem__(0, clock[0]+d))

    def test_clearance_overlaps_worker_startup(self):
        result = self.run_case(worker_at=.8)
        self.assertLess(result['total_s'], .82)  # no extra .5 s after worker readiness

    def test_no_fixed_one_second_wait(self):
        result = self.run_case()
        self.assertGreaterEqual(result['total_s'], .5)
        self.assertLess(result['total_s'], .52)

    def test_stale_or_blocked_cloud_and_missing_worker_never_ready(self):
        for kwargs in ({'fresh': False}, {'obstacle': True}, {'worker_at': 2.}):
            with self.assertRaisesRegex(RuntimeError, 'preflight_not_ready'):
                self.run_case(**kwargs)

    def test_takeover_during_initialization_fails_immediately(self):
        with self.assertRaisesRegex(RuntimeError, 'remote_takeover'):
            self.run_case(worker_at=2., guard='remote_takeover')


